"""Kinematics from a pixel track. Every number here is computed, never generated by a model."""
from __future__ import annotations

from dataclasses import asdict, dataclass, field

import numpy as np
from scipy.interpolate import UnivariateSpline

G = 9.80665


@dataclass
class Kinematics:
    takeoff_frame: int
    landing_frame: int
    airborne_s: float
    g_fit: float                 # free-fall acceleration fitted to the flight; self-check of scale x time
    g_fit_rel_err: float         # (g_fit - G) / G
    fit_rms_mm: float
    v0_ballistic: float          # take-off speed from the flight parabola, m/s (primary estimate)
    v0_ci95: tuple[float, float]  # residual-bootstrap 95% interval of v0_ballistic
    angle_deg: float
    height_mm: float
    distance_mm: float
    v_max_spline: float          # max speed of a smoothing spline of cumulative path (the common method in papers)
    v_max_range: tuple[float, float]  # same, over a range of smoothing strengths
    ax_fit: float = 0.0          # horizontal acceleration of the flight, m/s^2 (free flight: 0)
    ax_rel_g: float = 0.0        # |ax_fit| / |g_fit|: free-flight self-check, independent of scale and frame rate
    notes: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        return asdict(self)


def to_metres(frames: np.ndarray, cx: np.ndarray, cy: np.ndarray, mm_per_px: float):
    x = (cx - cx[0]) * mm_per_px / 1000.0
    y = -(cy - cy[0]) * mm_per_px / 1000.0      # image y points down
    return frames.astype(int), x, y


def flight_window(y: np.ndarray, lift_m: float) -> tuple[int, int]:
    """First index above `lift_m` and first index after the apex back below it."""
    up = np.where(y > lift_m)[0]
    if len(up) == 0:
        raise ValueError("The object never leaves the ground in this clip.")
    start = int(up[0])
    apex = int(np.argmax(y))
    down = np.where(y[apex:] < lift_m)[0]
    end = apex + int(down[0]) if len(down) else len(y) - 1
    if end - start < 10:
        raise ValueError("Flight is shorter than 10 frames; too short to fit.")
    return start, end


def kinematics(frames: np.ndarray, cx: np.ndarray, cy: np.ndarray, capture_fps: float, mm_per_px: float,
               lift_mm: float = 0.5, trim: int = 5) -> Kinematics:
    f, x, y = to_metres(frames, cx, cy, mm_per_px)
    notes: list[str] = []
    gaps = np.diff(f)
    if (gaps != 1).any():
        notes.append(f"{int((gaps != 1).sum())} gaps in the track (missing frames); fits use true frame times.")
    t = (f - f[0]) / capture_fps
    i0, i1 = flight_window(y, lift_mm / 1000.0)
    a = slice(i0 + trim, i1 - trim)
    tt = t[a] - t[i0]
    py = np.polyfit(tt, y[a], 2)
    px = np.polyfit(tt, x[a], 1)
    g_fit = -2.0 * py[0]
    ax_fit = 2.0 * np.polyfit(tt, x[a], 2)[0]
    resid = y[a] - np.polyval(py, tt)
    # Take-off = where the fitted parabola leaves the starting height (y = 0), which lies slightly before the
    # first frame above the lift threshold; evaluate the velocity there, not at the threshold crossing.
    roots = np.roots(py)
    roots = roots[np.isreal(roots)].real
    before = roots[roots <= 0]
    t_off = float(before.max()) if len(before) else 0.0
    vy0, vx0 = 2 * py[0] * t_off + py[1], px[0]
    v0_ci = _bootstrap_v0(tt, x[a], y[a], py, px)

    # Speed from a smoothing spline of the cumulative path (the usual method in jumping papers), taken only
    # around take-off so landing impacts cannot set the maximum. Smoothing strength is tied to the measured
    # track noise (rms of the flight fit), over a 1x-4x range; the spread becomes part of the interval.
    disp = np.concatenate([[0.0], np.cumsum(np.hypot(np.diff(x), np.diff(y)))])
    noise = max(float(resid.std()), 1e-7)
    i_end = min(i0 + max(10, (i1 - i0) // 4), len(t) - 1)
    vmax = []
    for factor in (1.0, 2.0, 4.0):
        s = UnivariateSpline(t, disp, s=len(t) * (factor * noise) ** 2)
        vmax.append(float(s.derivative()(t[: i_end + 1]).max()))

    return Kinematics(
        takeoff_frame=int(f[i0]), landing_frame=int(f[i1]), airborne_s=float(t[i1] - t[i0]),
        g_fit=float(g_fit), g_fit_rel_err=float((g_fit - G) / G), fit_rms_mm=float(resid.std() * 1000),
        v0_ballistic=float(np.hypot(vx0, vy0)), v0_ci95=v0_ci, angle_deg=float(np.degrees(np.arctan2(vy0, vx0))),
        height_mm=float(y.max() * 1000), distance_mm=float((x[i1] - x[i0]) * 1000),
        v_max_spline=float(vmax[1]), v_max_range=(min(vmax), max(vmax)), ax_fit=float(ax_fit),
        ax_rel_g=float(abs(ax_fit) / max(abs(g_fit), 1e-9)), notes=notes)


def repair_dropped_frames(frames: np.ndarray, cx: np.ndarray, cy: np.ndarray, mm_per_px: float,
                          lift_mm: float = 0.5, trim: int = 3, min_step_px: float = 1.0,
                          min_events: int = 3, max_period_cv: float = 0.1) -> tuple[np.ndarray, list[int]]:
    """Edited videos (montages, speed changes) can silently skip frames. In free flight the object moves a
    near-constant distance per frame, so a skipped frame shows up as one step about twice as long as both of
    its neighbours and pointing the same way. Editing software drops frames at a regular interval, so a repair
    is made only when at least `min_events` such steps occur periodically; isolated long steps (pixel
    quantisation, tracking jitter) are left alone. Returns frame indices with each skipped frame re-inserted in
    the timeline, and the track positions where that happened. Only the flight interior is examined."""
    f = frames.astype(int).copy()
    _, _, y = to_metres(f, cx, cy, mm_per_px)
    try:
        i0, i1 = flight_window(y, lift_mm / 1000.0)
    except ValueError:
        return f, []
    d = np.stack([np.diff(cx), np.diff(cy)], axis=1)
    step = np.hypot(d[:, 0], d[:, 1])
    found: list[int] = []
    for i in range(i0 + trim + 1, i1 - trim - 1):
        if f[i + 1] - f[i] != 1:
            continue
        local = np.median(step[max(i0 + trim, i - 7):min(i1 - trim, i + 8)])
        if local < min_step_px:
            continue
        neighbours_normal = all(0.75 <= step[n] / local <= 1.33 for n in (i - 1, i + 1))
        same_direction = np.hypot(*(d[i] - d[i - 1] - d[i + 1])) < 0.3 * step[i]
        if 1.7 <= step[i] / local <= 2.5 and neighbours_normal and same_direction:
            found.append(i)
    if len(found) < min_events:
        return f, []
    # The strict detections must sit on one regular period (gaps are whole multiples of it, as when a few
    # strict tests fail in between). Then every long step on that period is taken, with a relaxed test.
    base = float(np.median(np.diff(found)))
    kept: list[int] = []
    for i in found:   # two candidates closer than half a period: keep the one nearer a clean 2x step
        if kept and i - kept[-1] < 0.5 * base:
            if abs(step[i] / np.median(step[i0:i1]) - 2) < abs(step[kept[-1]] / np.median(step[i0:i1]) - 2):
                kept[-1] = i
            continue
        kept.append(i)
    found = kept
    if len(found) < min_events:
        return f, []
    gaps = np.diff(found)
    base = float(np.median(gaps))
    mult = np.round(gaps / base)
    if base < 4 or (np.abs(gaps - mult * base) > max(1.5, max_period_cv * base)).any():
        return f, []
    period = (found[-1] - found[0]) / mult.sum()
    k = np.arange(np.floor((i0 - found[0]) / period), np.ceil((i1 - found[0]) / period) + 1)
    predicted = found[0] + k * period
    chain = []
    for i in range(i0 + trim + 1, i1 - trim - 1):
        if f[i + 1] - f[i] != 1 or np.abs(predicted - i).min() > 1.0:
            continue
        local = np.median(step[max(i0 + trim, i - 7):min(i1 - trim, i + 8)])
        if local >= min_step_px and 1.7 <= step[i] / local <= 2.5:
            chain.append(i)
    found = sorted(set(chain) | set(found))
    extra = np.zeros(len(step), int)
    extra[found] = 1
    return f + np.concatenate([[0], np.cumsum(extra)]), found


def _bootstrap_v0(tt, x, y, py, px, n=400, block=12, seed=0) -> tuple[float, float]:
    # Moving-block bootstrap of the fit residuals: track errors are correlated frame to frame
    # (masks change slowly), so resampling single frames would understate the uncertainty.
    rng = np.random.default_rng(seed)
    ry, rx = y - np.polyval(py, tt), x - np.polyval(px, tt)
    m = len(tt)
    block = max(1, min(block, m // 4))
    out = []
    for _ in range(n):
        starts = rng.integers(0, m - block + 1, int(np.ceil(m / block)))
        idx = np.concatenate([np.arange(s0, s0 + block) for s0 in starts])[:m]
        by = np.polyfit(tt, np.polyval(py, tt) + ry[idx], 2)
        bx = np.polyfit(tt, np.polyval(px, tt) + rx[idx], 1)
        r = np.roots(by)
        r = r[np.isreal(r)].real
        r = r[r <= 0]
        t0 = float(r.max()) if len(r) else 0.0
        out.append(np.hypot(bx[0], 2 * by[0] * t0 + by[1]))
    lo, hi = np.percentile(out, [2.5, 97.5])
    return float(lo), float(hi)


def speed_interval(k: Kinematics, scale_rel_unc: float, fps_rel_unc: float = 0.0) -> tuple[float, float, float]:
    """Primary estimate = ballistic take-off speed. Interval = its block-bootstrap 95% CI, widened by the
    systematic uncertainty of scale and frame rate. The gravity self-check bounds that systematic error:
    a length-scale error e gives g and v the same relative error e, so |g_fit/G - 1| is added in quadrature."""
    sys_rel = float(np.sqrt(scale_rel_unc ** 2 + fps_rel_unc ** 2 + k.g_fit_rel_err ** 2))
    lo, hi = k.v0_ci95
    return k.v0_ballistic, lo * (1 - sys_rel), hi * (1 + sys_rel)


def gravity_timebase(frames: np.ndarray, cx: np.ndarray, cy: np.ndarray, mm_per_px: float,
                     lift_mm: float = 0.5, trim: int = 5, n: int = 400, block: int = 12, seed: int = 0):
    """Frame rate implied by free fall when the video does not state its playback speed: the flight parabola
    measured per *video frame* must curve at g = 9.81 m/s^2, so fps = sqrt(G / g_per_frame^2).
    Returns (fps, lo95, hi95). Speeds then scale with sqrt(length scale), halving the effect of a scale error."""
    f, x, y = to_metres(frames, cx, cy, mm_per_px)
    t = (f - f[0]).astype(float)
    i0, i1 = flight_window(y, lift_mm / 1000.0)
    a = slice(i0 + trim, i1 - trim)
    tt, yy = t[a] - t[i0], y[a]
    py = np.polyfit(tt, yy, 2)
    g_frame = -2.0 * py[0]
    if g_frame <= 0:
        raise ValueError("flight is not curving downwards; cannot infer a time base from gravity")
    rng = np.random.default_rng(seed)
    r = yy - np.polyval(py, tt)
    m = len(tt)
    block = max(1, min(block, m // 4))
    samples = []
    for _ in range(n):
        starts = rng.integers(0, m - block + 1, int(np.ceil(m / block)))
        idx = np.concatenate([np.arange(s0, s0 + block) for s0 in starts])[:m]
        g_b = -2.0 * np.polyfit(tt, np.polyval(py, tt) + r[idx], 2)[0]
        if g_b > 0:
            samples.append(np.sqrt(G / g_b))
    lo, hi = np.percentile(samples, [2.5, 97.5])
    return float(np.sqrt(G / g_frame)), float(lo), float(hi)
